mapper.insert:
INSERT INTO expense_budget_retention(tenant_id,report_id,application_id,round_no,stopped_status,
    retained_at,retention_days,expires_at,status,version,state_json,updated_at,trace_id)
SELECT r.tenant_id,r.id,r.application_id,s.round_no,s.status,s.completed_at,#{retentionDays},#{expiresAt},'RETAINED',1,#{stateJson},#{updatedAt},#{traceId}
FROM expense_report r JOIN approval_submission_round s
    ON s.tenant_id=r.tenant_id AND s.application_id=r.application_id
WHERE r.tenant_id=#{tenantId} AND r.id=#{reportId} AND r.application_id=#{applicationId} AND s.round_no=#{roundNo} AND s.status=#{stoppedStatus} AND s.completed_at=#{retainedAt}

mapper.update:
UPDATE expense_budget_retention SET status=#{status},release_operation_id=#{releaseOperationId},version=#{version},state_json=#{stateJson},updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND report_id=#{reportId} AND round_no=#{roundNo} AND application_id=#{applicationId} AND stopped_status=#{stoppedStatus}
    AND retained_at=#{retainedAt} AND retention_days=#{retentionDays} AND expires_at=#{expiresAt} AND version=#{expectedVersion}

mapper.select:

SELECT r.tenant_id,r.report_id,r.round_no,r.trace_id,business.business_no,submitted.process_instance_id FROM expense_budget_retention r
LEFT JOIN approval_application business ON business.tenant_id=r.tenant_id AND business.id=r.application_id
LEFT JOIN approval_submission_round submitted ON submitted.tenant_id=business.tenant_id AND submitted.application_id=business.id AND submitted.round_no=r.round_no
WHERE r.status IN ('RETAINED','RECONCILING','RELEASE_QUEUED') AND r.expires_at<=#{argument1}
 AND (r.tenant_id>#{argument2} OR (r.tenant_id=#{argument3} AND r.report_id>#{argument4}) OR (r.tenant_id=#{argument5} AND r.report_id=#{argument6} AND r.round_no>#{argument7})) ORDER BY r.tenant_id,r.report_id,r.round_no LIMIT #{argument8}
